#!/usr/bin/env python3
import argparse
import sys
import json
import base64
import logging

def decode_jwt(token):
    """Decode JWT header and payload without verification."""
    parts = token.split('.')
    if len(parts) != 3:
        raise ValueError("Invalid JWT: expected 3 parts separated by dots")

    header_b64, payload_b64, _ = parts

    # Add padding if necessary
    def add_padding(data):
        return data + '=' * (-len(data) % 4)

    try:
        header_bytes = base64.urlsafe_b64decode(add_padding(header_b64))
        payload_bytes = base64.urlsafe_b64decode(add_padding(payload_b64))
    except Exception as e:
        raise ValueError(f"Base64 decoding failed: {e}")

    try:
        header = json.loads(header_bytes)
        payload = json.loads(payload_bytes)
    except json.JSONDecodeError as e:
        raise ValueError(f"JSON parsing failed: {e}")

    return header, payload

def main():
    parser = argparse.ArgumentParser(description="Decode a JWT token and print its header and payload.")
    parser.add_argument('jwt', nargs='?', help="JWT token to decode. If omitted, read from stdin.")
    args = parser.parse_args()

    if args.jwt:
        token = args.jwt
    else:
        token = sys.stdin.read().strip()
        if not token:
            parser.print_help()
            sys.exit(1)

    try:
        header, payload = decode_jwt(token)
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

    # Pretty print
    print("Header:")
    print(json.dumps(header, indent=2))
    print("\nPayload:")
    print(json.dumps(payload, indent=2))

if __name__ == "__main__":
    main()